// Design's reference workflow requires vision even when its internal catalog
// supplies the images. With no user attachments, continue as ordinary coding.
export function selectDesignMode(attachments, isDesignBrief, supportsImages) {
    const requested = attachments.some(isDesignBrief);
    const references = attachments.filter((attachment) => !isDesignBrief(attachment));
    if (!requested || supportsImages)
        return { design: requested, textOnly: false, blocked: false, attachments };
    return { design: false, textOnly: true, blocked: false, attachments: references };
}
